rf=[('RF-01','Registro de estudiantes','Crear cuenta STUDENT con nombre de 2-80 caracteres, correo único de hasta 120 y contraseña de 10-128 con mayúscula, minúscula y número. El cliente no puede elegir ADMIN.'),('RF-02','Autenticación y cierre','Validar credenciales, emitir token aleatorio de 256 bits, conservar sesión por 8 horas y revocarla al cerrar sesión.'),('RF-03','Autorización','Rechazar acceso anónimo, reservar operaciones de administración para ADMIN y limitar a STUDENT la consulta/cancelación de sus propias reservas.'),('RF-04','Catálogo','Mostrar código, nombre, categoría, descripción y estado; permitir búsqueda local por nombre, código y categoría.'),('RF-05','Gestión de equipos','Crear equipos con código único y cambiar AVAILABLE, MAINTENANCE o RETIRED; bloquear mantenimiento/retiro si existen reservas aprobadas o préstamos activos.'),('RF-06','Solicitud de reserva','Registrar equipo disponible, inicio futuro hasta 30 días, duración de 1-8 horas, precisión de minutos y propósito de 10-300 caracteres.'),('RF-07','Cupo de reservas','Limitar cada usuario a tres reservas activas: REQUESTED, APPROVED y CHECKED_OUT, incluso ante solicitudes concurrentes.'),('RF-08','Decisión administrativa','Aprobar o rechazar solicitudes REQUESTED; aprobar solo antes de iniciar y mientras equipo y horario continúen disponibles.'),('RF-09','Exclusión temporal','Impedir solapamiento de intervalos aprobados o en préstamo. Intervalos [inicio,fin): terminar exactamente cuando otro inicia es válido.'),('RF-10','Cancelación','Permitir a propietario o administrador cancelar REQUESTED o APPROVED antes del inicio. Liberar cupo y horario.'),('RF-11','Entrega del equipo','Cambiar APPROVED a CHECKED_OUT solo por ADMIN, desde 15 minutos antes del inicio hasta antes del fin, y sin otro préstamo de ese equipo pendiente de devolución.'),('RF-12','Devolución','Cambiar CHECKED_OUT a RETURNED por ADMIN una sola vez; registrar fecha y retraso en minutos, redondeado hacia arriba y nunca negativo.'),('RF-13','Resumen','Consultar conteos de reservas por estado y total de equipos. Estudiante ve sus reservas; administrador ve todas.'),('RF-14','Auditoría operacional','Registrar actor, acción, entidad y fecha para creación de reserva/equipo, cambios de estado y decisiones. Restringir consulta de los últimos 100 eventos a ADMIN.')]
rnf=[('RNF-01','Rendimiento','En QA cloud, con rampa 0-50 VU en 1 min y 50 VU durante 5 min, p95 <2000 ms en catálogo y resumen; tasa de errores <1%.','CP-61','Pendiente cloud'),('RNF-02','Seguridad','100% de rutas protegidas probadas rechazan anónimos/roles no permitidos; sesión expira a 8 h; intento 11 falla con 429 tras diez errores; ninguna respuesta de identidad expone hashes.','CP-08,09,11,33,45,48,57,58','Verificado local; SCA residual separado'),('RNF-03','Consistencia','Dos aprobaciones concurrentes del mismo horario producen exactamente una aprobación; cuatro creaciones concurrentes de un usuario aceptan como máximo tres.','CP-49,52','Verificado local; repetir con PostgreSQL cloud'),('RNF-04','Persistencia','Tras cerrar y reabrir la misma base, se conserva el 100% de los campos del equipo de prueba; repetir después de reiniciar el backend cloud.','CP-62,65','Verificado local; cloud pendiente'),('RNF-05','Usabilidad y compatibilidad','Flujo login-solicitud-aprobación-historial sin errores JavaScript; sin scroll horizontal a 390 px y 1440 px; tildes del propósito conservadas.','CP-56,63','Verificado en Chromium local'),('RNF-06','Mantenibilidad','Al menos 30 pruebas unitarias entre backend/frontend, tres con dobles; líneas >=80% en alcance declarado y mejora >=20 puntos en módulos críticos de línea base.','CP-64','90 pruebas; mejora 100 pp local'),('RNF-07','Errores controlados','Cuerpo ausente, JSON inválido y carga >16 KiB producen respectivamente 400, 400 y 413 con código/mensaje, sin trazas de servidor.','CP-50,53,54','Verificado local'),('RNF-08','Despliegue y acceso','Backend y frontend se construyen por separado; dos URL HTTPS operativas y accesibles desde sesión independiente; reserva conservada después del reinicio cloud.','CP-65','Build local aprobado; cloud pendiente')]
