x.table(['Campo','Información'],[['Nombre','ReservaLab'],['Origen','Aplicación generada con IA bajo especificación del estudiante; no se evalúa su construcción.'],['Responsable','ERICK ESTUARDO CRUZ ROMERO, 0900-19-1362'],['Roles','Analista de Pruebas, Ingeniero de Automatización e Ingeniero de Plataforma/DevOps, asumidos por Erick.'],['Tecnologías','React + Vite; Node.js 24 + Express; PGlite local / PostgreSQL cloud.'],['Licencia','MIT para código original; licencias de dependencias conservadas.'],['Repositorio y URL','Pendientes de publicación; no existe registro previo en el curso.'],['Línea base','Tag baseline-v0, sin pruebas automatizadas de origen; instrumentación sin tests: 0% en domain.js y rules.js.'],['Estado','Preparado para registrar, no registrado ni aprobado por el catedrático.']],[142,362])
x.h('2. E1 · Descripción y alcance',new=True)
x.p('ReservaLab apoya al laboratorio que comparte equipos entre estudiantes. Sustituye una agenda informal por solicitudes con reglas de duración y disponibilidad, aprobación administrativa, entrega y devolución. El resultado esperado del negocio es evitar comprometer un mismo equipo en horarios incompatibles y conservar quién autorizó cada operación.')
x.p('El estudiante consulta equipos, solicita horarios y cancela antes del inicio. El administrador agrega equipos, gestiona mantenimiento, aprueba/rechaza solicitudes y registra movimientos físicos. Ambos roles pueden consultar su información; solo el administrador ve todas las reservas y la auditoría.')
x.p('Alcance: un laboratorio, equipos identificables individualmente, reservas de una sola unidad, tiempos registrados como milisegundos UTC y mostrados en la zona del dispositivo. No incluye cobros, correo, facturación, geolocalización ni integración con inventarios reales. Las solicitudes vencidas no expiran automáticamente: el administrador debe rechazarlas para liberar el cupo; esta limitación está declarada.')
x.h('2.1 Reglas de negocio',2)
x.table(['Regla','Definición'],[['RB-01','Sesión de ocho horas, rol verificado en servidor.'],['RB-02','Inicio estrictamente futuro y hasta 30 días; intervalos de 1 a 8 horas; precisión de minutos.'],['RB-03','Propósito de 10 a 300 caracteres después de quitar espacios externos.'],['RB-04','Máximo tres reservas en REQUESTED, APPROVED o CHECKED_OUT por usuario.'],['RB-05','Las solicitudes pueden competir; la aprobación vuelve a verificar disponibilidad bajo transacción.'],['RB-06','[inicio,fin) permite reservas contiguas pero no solapadas.'],['RB-07','Entrega desde inicio-15 min hasta antes del fin y sin préstamo anterior sin devolver.'],['RB-08','Devolución única; retraso=max(0,ceil((devuelto-fin)/60 000)).'],['RB-09','No pasar a mantenimiento o retirado un equipo con reservas aprobadas o préstamos activos.']],[65,439])
x.h('2.2 Casos de uso principales',new=True)
for id,title,actor,pre,flow,alt,refs in usecases:
 x.h(id+' · '+title,2);x.table(['Elemento','Descripción'],[['Actor',actor],['Precondición',pre],['Flujo principal',flow],['Flujo alterno',alt],['Requerimientos',refs]],[100,404])
